<form method="post" action="/admin/settings"><?= csrf_field() ?><div class="settings-grid"><section class="panel"><div class="panel-head"><div><h2>Site identity</h2><p>Core public-facing information.</p></div></div><div class="field"><label>Site name</label><input name="site_name" value="<?= e($values['site_name']??'') ?>" required></div><div class="field"><label>Tagline</label><input name="site_tagline" value="<?= e($values['site_tagline']??'') ?>"></div><div class="field"><label>Site description</label><textarea class="short" name="site_description"><?= e($values['site_description']??'') ?></textarea></div><div class="field"><label>Footer text</label><input name="footer_text" value="<?= e($values['footer_text']??'') ?>"></div></section><section class="panel"><div class="panel-head"><div><h2>Reading & SEO</h2><p>Defaults used by themes and public archives.</p></div></div><div class="field"><label>Homepage SEO title</label><input name="homepage_title" value="<?= e($values['homepage_title']??'') ?>"></div><div class="field"><label>Posts per page</label><input name="posts_per_page" type="number" min="1" max="50" value="<?= e($values['posts_per_page']??'10') ?>"></div><label class="toggle-row"><input type="checkbox" name="search_engine_visibility" value="1"<?= checked(($values['search_engine_visibility']??'0')==='1') ?>><span><strong>Discourage search engines</strong><small>Adds a noindex directive to bundled themes.</small></span></label></section></div><div class="form-footer"><button class="btn primary" type="submit">Save settings</button></div></form>